function envelope(string$event,array$form,array$query=[]):array{global$account,$sid,$binding,$gateway;return ['v'=>1,'client'=>'alpha','destination'=>'a','event'=>$event,'call_sid'=>$sid,'account_sid'=>$account,'number'=>'+10000000081','gateway_base'=>$gateway,'binding'=>$binding,'method'=>$event==='whisper'?'GET':'POST','query'=>$query,'form'=>$form,'timestamp'=>time(),'nonce'=>bin2hex(random_bytes(32))];}
function invoke(array$v,array$rows=[],array$override=[]):array{global$client,$root,$secret;$raw=json_encode($v,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES);return worker(array_replace(['mode'=>'gateway','envelope'=>$raw,'handoff_signature'=>hash_hmac('sha256',$raw,$secret),'gateway_clients'=>$client,'nonce_dir'=>$root.'/nonces','webroot'=>$root.'/web/','rows'=>$rows,'number'=>['record_calls'=>1,'recording_notice'=>'Owned fixture notice','whisper_new'=>"New & repeat's fixture"]],$override));}
try{
 $v=envelope('voice',['AccountSid'=>$account,'CallSid'=>$sid,'From'=>'+10000000089','To'=>'+10000000081']);$r=invoke($v);check($r['status']===200&&count($r['rows'])===1&&$r['rows'][0]['transaction_id']==='twilio:'.$sid,'authenticated voice persists canonical identity');
 $xml=html_entity_decode($r['output'],ENT_QUOTES|ENT_XML1);foreach(['status','recording','whisper']as$e)check(str_contains($xml,'event='.$e.'&call='.$sid.'&binding='.$binding),'actual TwiML central '.$e.' URL');check(strpos($xml,'Owned fixture notice')<strpos($xml,'<Dial')&&str_contains($xml,'record-from-answer-dual'),'notice and dual recording preserved');
