 $w=envelope('whisper',[],['AccountSid'=>$account,'CallSid'=>'CA'.str_repeat('2',32),'ParentCallSid'=>$sid,'msg'=>"New & repeat's fixture"]);$r=invoke($w,$rows);check($r['status']===200&&str_contains($r['output'],'New &amp; repeat&apos;s fixture'),'actual GET whisper renders escaped signed text');check($r['gateway_context_cleared']&&$r['method_restored'],'whisper restores original POST request globals');
 $status=envelope('status',['AccountSid'=>$account,'CallSid'=>$sid,'DialCallStatus'=>'completed','DialCallDuration'=>'65']);$r=invoke($status,$rows);check($r['status']===200&&$r['rows'][0]['qualification_status']==='qualified','actual status persists outcome');$rows=$r['rows'];
 $record=envelope('recording',['AccountSid'=>$account,'CallSid'=>$sid,'RecordingSid'=>'RE'.str_repeat('3',32),'RecordingUrl'=>'https://media.invalid/owned','RecordingStatus'=>'completed','RecordingDuration'=>'65']);$r=invoke($record,$rows);check($r['status']===200&&$r['rows'][0]['recording_sid']==='RE'.str_repeat('3',32),'actual recording persists marker');$rows=$r['rows'];
 $record['nonce']=bin2hex(random_bytes(32));$r=invoke($record,$rows);check($r['status']===200&&$r['rows']===$rows&&$r['writes']===[],'fresh authenticated duplicate recording is no-op');$r=invoke($record,$rows);check($r['status']===409&&$r['rows']===$rows,'exact internal replay rejected without writes');
 $late=envelope('status',['AccountSid'=>$account,'CallSid'=>$sid,'CallStatus'=>'ringing']);$r=invoke($late,$rows);check($r['status']===200&&$r['rows']===$rows,'late status preserves terminal outcome');
 $capture=$rows[0]['call_capture_json'];check(!empty($capture),'original acquisition capture created once');check($r['rows'][0]['call_capture_json']===$capture,'late callback preserves acquisition capture');
 $p=['CallSid'=>$sid,'To'=>'+10000000081'];$r=worker(['mode'=>'signature','post'=>$p,'server_headers'=>['HTTP_X_SECB_HANDOFF'=>'forged','HTTP_X_FORWARDED_HOST'=>'gateway.fixture.invalid','HTTP_X_FORWARDED_PROTO'=>'https']]);check($r['output']==='false','forwarding headers cannot bypass direct signature validation');
}finally{foreach($files as$f)if(is_file($f))unlink($f);foreach(glob($root.'/nonces/*')as$f)unlink($f);rmdir($root.'/nonces');rmdir($root.'/web');rmdir($root);}
